// Toma el archivo recibido (de la carpeta del corpus o del webhook),
// valida su formato y deja el binario en el campo "data".
const binarios = $input.item.binary || {};
const clave = Object.keys(binarios)[0];
if (!clave) {
  throw new Error('El elemento no trae ningún archivo.');
}
const archivo = binarios[clave];
const nombre = (archivo.fileName || '').trim();
const extension = (archivo.fileExtension || nombre.split('.').pop() || '').toLowerCase();
const PERMITIDOS = ['pdf', 'md', 'txt'];
if (!PERMITIDOS.includes(extension)) {
  throw new Error(`Formato no soportado: ${nombre}. Solo se aceptan PDF, MD o TXT.`);
}
return {
  json: { nombre_archivo: nombre.toLowerCase(), tipo_archivo: extension },
  binary: { data: archivo },
};

// Limpia el texto, lo divide en fragmentos con solape y conserva la sección y la página.
// Salida: metadatos del documento + fragmentos listos para generar embeddings.

const TAMANO_OBJETIVO = 1200;   // caracteres por fragmento
const TAMANO_MAXIMO = 1600;
const SOLAPE = 200;             // caracteres que se repiten entre fragmentos

// Documentos públicos: título y URL de origen (se citan en las respuestas)
const FUENTES_PUBLICAS = {
  'reglamento-estudiantil-pregrado.pdf': {
    titulo: 'Reglamento Estudiantil de Pregrado (UNAB, 2019)',
    url: 'https://unab.edu.co/NewFolder/Reglamento-estudiantil-pregraod.pdf',
  },
  'lineamientos-curriculares-pregrado.pdf': {
    titulo: 'Lineamientos curriculares de pregrado (UNAB, 2018)',
    url: 'https://unab.edu.co/NewFolder/Lineamientos-curriculares-pregrado.pdf',
  },
};

function leerFrontMatter(texto) {
  const m = texto.match(/^---\n([\s\S]*?)\n---\n/);
  if (!m) return { meta: {}, cuerpo: texto };
  const meta = {};
  for (const linea of m[1].split('\n')) {
    const i = linea.indexOf(':');
    if (i > 0) meta[linea.slice(0, i).trim()] = linea.slice(i + 1).trim();
  }
  return { meta, cuerpo: texto.slice(m[0].length) };
}

function limpiar(texto) {
  return texto
    .replace(/\r\n?/g, '\n')
    .replace(/­/g, '')                          // guiones suaves
    .replace(/([a-záéíóúñü])-\n([a-záéíóúñü])/gi, '$1$2') // palabras partidas al final de línea
    .replace(/^.*\.{5,}.*$/gm, '')                   // líneas de índice con puntos
    .replace(/^\s*\d{1,3}\s*$/gm, '')                // números de página sueltos
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const ES_TITULO = /^(#{1,6}\s+.+|T[IÍ]TULO\s+[A-ZÁÉÍÓÚ]+.*|CAP[IÍ]TULO\s+[A-ZÁÉÍÓÚ]+.*|ART[IÍ]CULO\s+\d+.*)$/i;

// Divide en párrafos y une las líneas cortadas de los PDF
function parrafos(texto) {
  const salida = [];
  for (const bloque of texto.split(/\n\s*\n/)) {
    const lineas = bloque.split('\n').map((l) => l.trim()).filter(Boolean);
    let actual = '';
    for (const linea of lineas) {
      if (ES_TITULO.test(linea) && !/^ART[IÍ]CULO/i.test(linea)) {
        if (actual) salida.push(actual);
        salida.push(linea);
        actual = '';
      } else if (/^ART[IÍ]CULO\s+\d+/i.test(linea)) {
        if (actual) salida.push(actual);
        actual = linea;
      } else if (/^([-*•]|\d+[.)])\s/.test(linea) || /^\|/.test(linea)) {
        actual = actual ? actual + '\n' + linea : linea;
      } else {
        actual = actual ? actual + ' ' + linea : linea;
      }
    }
    if (actual) salida.push(actual);
  }
  return salida;
}

function partirLargo(parrafo) {
  if (parrafo.length <= TAMANO_MAXIMO) return [parrafo];
  const oraciones = parrafo.match(/[^.!?;]+[.!?;]+|\S[^.!?;]*$/g) || [parrafo];
  const piezas = [];
  let actual = '';
  for (const o of oraciones) {
    if ((actual + ' ' + o).length > TAMANO_OBJETIVO && actual) {
      piezas.push(actual.trim());
      actual = o;
    } else {
      actual += ' ' + o;
    }
  }
  if (actual.trim()) piezas.push(actual.trim());
  return piezas;
}

function solape(texto) {
  if (texto.length <= SOLAPE) return texto;
  const cola = texto.slice(-SOLAPE);
  const corte = cola.search(/[.!?;]\s/);
  return corte >= 0 ? cola.slice(corte + 2) : cola;
}

// Datos del archivo y su texto (vienen del nodo "Calcular hash")
const fuente = $('Calcular hash').item.json;
const nombre = fuente.nombre_archivo;
const tipo = fuente.tipo_archivo;
const paginas = Array.isArray(fuente.text) ? [...fuente.text] : [fuente.texto || fuente.text || ''];

let meta = {};
if (tipo === 'md' || tipo === 'txt') {
  const fm = leerFrontMatter(paginas[0].replace(/\r\n?/g, '\n'));
  meta = fm.meta;
  paginas[0] = fm.cuerpo;
}

const fragmentos = [];
let seccion = '';
let actual = '';
let paginaInicio = null;

function cerrar(paginaFin) {
  const contenido = actual.trim();
  if (contenido.length >= 80) {
    fragmentos.push({
      indice: fragmentos.length,
      contenido,
      pagina: tipo === 'pdf' ? paginaInicio : null,
      seccion: seccion.replace(/^#+\s*/, '').slice(0, 250) || null,
    });
  }
  actual = contenido ? solape(contenido) : '';
  paginaInicio = paginaFin;
}

paginas.forEach((textoPagina, i) => {
  const numPagina = i + 1;
  for (const p of parrafos(limpiar(textoPagina))) {
    if (ES_TITULO.test(p) && !/^ART[IÍ]CULO/i.test(p)) {
      if (actual.length > 300) cerrar(numPagina);
      seccion = p;
      continue;
    }
    for (const pieza of partirLargo(p)) {
      if (paginaInicio === null) paginaInicio = numPagina;
      if ((actual + '\n' + pieza).length > TAMANO_OBJETIVO && actual.length > SOLAPE) {
        cerrar(numPagina);
      }
      actual = actual ? actual + '\n' + pieza : pieza;
    }
  }
});
if (actual.trim()) cerrar(null);

const publica = FUENTES_PUBLICAS[nombre];
const titulo = meta.titulo || (publica && publica.titulo) || nombre.replace(/\.[^.]+$/, '').replace(/[-_]/g, ' ');
const origen = meta.origen || (publica ? 'publico' : 'demostrativo');

return {
  json: {
    documento: {
      nombre_archivo: nombre,
      titulo,
      descripcion: origen === 'demostrativo' ? 'Documento demostrativo (contenido sintético)' : 'Documento público de la UNAB',
      tipo_archivo: tipo,
      origen,
      url_origen: publica ? publica.url : (meta.url || ''),
      hash_contenido: fuente.hash_contenido,
    },
    // Texto que se envía a Voyage: incluye título y sección para dar contexto
    fragmentos: fragmentos.map((f) => ({
      ...f,
      texto_embedding: `Documento: ${titulo}\n${f.seccion ? 'Sección: ' + f.seccion + '\n' : ''}${f.contenido}`,
    })),
  },
};

// Agrupa los fragmentos en lotes para Voyage AI (un lote = una petición).
// Lotes de 24 fragmentos con 1 s de pausa entre peticiones (límites de Voyage nivel 1).
const TAMANO_LOTE = 24;
const salida = [];
$input.all().forEach((item, d) => {
  const { fragmentos } = item.json;
  for (let i = 0; i < fragmentos.length; i += TAMANO_LOTE) {
    salida.push({
      json: {
        documento_indice: d,
        desde: i,
        textos: fragmentos.slice(i, i + TAMANO_LOTE).map((f) => f.texto_embedding),
      },
    });
  }
});
return salida;

// Une cada embedding con su fragmento y arma un elemento por documento.
const DIMENSION = 1024;
const lotes = $('Preparar lotes').all();
const documentos = $('Limpiar y fragmentar').all();
const respuestas = $input.all();

if (respuestas.length !== lotes.length) {
  throw new Error(`Se esperaban ${lotes.length} respuestas de Voyage y llegaron ${respuestas.length}.`);
}

const vectores = documentos.map((d) => new Array(d.json.fragmentos.length));
respuestas.forEach((respuesta, i) => {
  const lote = lotes[i].json;
  const datos = respuesta.json.data;
  if (!Array.isArray(datos) || datos.length !== lote.textos.length) {
    throw new Error(`El lote ${i} devolvió ${Array.isArray(datos) ? datos.length : 0} embeddings para ${lote.textos.length} textos.`);
  }
  [...datos]
    .sort((a, b) => a.index - b.index)
    .forEach((e, j) => {
      vectores[lote.documento_indice][lote.desde + j] = e.embedding;
    });
});

return documentos.map((d, k) => ({
  json: {
    documento: d.json.documento,
    fragmentos: d.json.fragmentos.map((f, i) => {
      const vector = vectores[k][i];
      if (!Array.isArray(vector) || vector.length !== DIMENSION) {
        throw new Error(`Falta el embedding del fragmento ${i} de ${d.json.documento.nombre_archivo}.`);
      }
      return {
        indice: f.indice,
        contenido: f.contenido,
        pagina: f.pagina,
        seccion: f.seccion,
        embedding: vector,
      };
    }),
  },
}));
